#!/usr/bin/env bash
# Standalone installer generated by build_installer.py.
set -Eeuo pipefail
umask 077

die() { printf 'Ошибка: %s\n' "$*" >&2; exit 1; }
if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
    cat <<'HELP'
Использование: sudo bash install.sh
Shinobi на Debian 12/13 или Ubuntu 22.04/24.04/26.04/26.10 с systemd.
Выбор внешнего USB-раздела, монтирование по UUID, Docker, автозапуск.
Существующая файловая система сохраняется; форматирования нет.
При повторном запуске используются прежние диск, учётные записи и образы.
HELP
    exit 0
fi
[[ $# -eq 0 ]] || die 'Неизвестные параметры; используйте --help.'
[[ "$(uname -s)" == Linux ]] || die 'Запустите установщик на Linux-компьютере для регистратора.'
[[ "$EUID" -eq 0 ]] || die "Запустите: sudo bash $0"
[[ -r /etc/os-release && -d /run/systemd/system ]] || die 'Требуется Debian/Ubuntu с systemd.'
# OS-owned identification file.
# shellcheck disable=SC1091
. /etc/os-release
case "${ID:-}:${VERSION_ID:-}" in
    debian:12|debian:13|ubuntu:22.04|ubuntu:24.04|ubuntu:26.04|ubuntu:26.10) ;;
    *) die 'Поддерживаются Debian 12/13 и Ubuntu 22.04/24.04/26.04/26.10.' ;;
esac
case "$(dpkg --print-architecture)" in amd64|arm64) ;; *) die 'Нужна архитектура amd64 или arm64.' ;; esac
INSTALLER="$(readlink -f -- "${BASH_SOURCE[0]}")"
[[ -f "$INSTALLER" ]] || die 'Сначала сохраните install.sh в файл.'
WORK_DIR=''
cleanup() { [[ -z "$WORK_DIR" ]] || rm -rf -- "$WORK_DIR"; }
trap cleanup EXIT
trap 'printf "Установка остановилась в строке %s. Данные не удалялись.\n" "$LINENO" >&2' ERR
apt_install() { DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends --no-remove "$@"; }
missing=()
for item in python3 curl lsblk findmnt; do
    if ! command -v "$item" >/dev/null; then
        case "$item" in lsblk|findmnt) missing+=(util-linux) ;; *) missing+=("$item") ;; esac
    fi
done
[[ -s /etc/ssl/certs/ca-certificates.crt ]] || missing+=(ca-certificates)
if [[ ${#missing[@]} -gt 0 ]]; then apt-get update; apt_install "${missing[@]}"; fi

package_installed() { [[ "$(dpkg-query -W -f='${Status}' "$1" 2>/dev/null || true)" == 'install ok installed' ]]; }
if ! command -v docker >/dev/null; then
    for package in docker.io docker-compose docker-compose-v2 docker-doc docker-buildx podman-docker containerd runc; do
        ! package_installed "$package" || die "Установлен $package. Настройте Docker/Compose вручную; существующие пакеты автоматически не удаляются."
    done
    install -d -m 0755 /etc/apt/keyrings
    key="$(mktemp /etc/apt/keyrings/docker.asc.XXXXXX)"
    curl --fail --silent --show-error --location --retry 3 --connect-timeout 15 --max-time 90 \
        "https://download.docker.com/linux/$ID/gpg" -o "$key"
    chmod 0644 "$key"
    mv -f -- "$key" /etc/apt/keyrings/docker.asc
    printf 'deb [arch=%s signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/%s %s stable\n' \
        "$(dpkg --print-architecture)" "$ID" "$VERSION_CODENAME" > /etc/apt/sources.list.d/fcplcn-docker.list
    apt-get update
    apt_install docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
    systemctl enable --now docker
fi
unset DOCKER_CONTEXT
export DOCKER_HOST=unix:///var/run/docker.sock
if ! docker compose version >/dev/null 2>&1; then
    if package_installed docker-ce-cli; then
        apt-get update; apt_install docker-compose-plugin
    elif package_installed docker.io && apt-cache show docker-compose-v2 >/dev/null 2>&1; then
        apt-get update; apt_install docker-compose-v2
    else
        die 'Нужен Docker Compose v2. Установите его и повторите запуск.'
    fi
fi
docker info >/dev/null 2>&1 || die 'Docker не запущен. Проверьте systemctl status docker.'
WORK_DIR="$(mktemp -d /tmp/fcplcn-shinobi.XXXXXXXX)"
cat > "$WORK_DIR/setup.py" <<'__FCPLCN_SHINOBI_PYTHON__'
